'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { WordRoll } from '@/components/core/word-roll';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { SearchIcon } from '@/registry/ndeko/lib/icons';
import {
  EASE_OUT_STRONG,
  INSTANT,
  rowPresenceOf,
  SLOW_SPRING,
} from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { Input } from '@/registry/ndeko/ui/input';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { BLOG, TOPICS } from './data';
import { FeaturedPost, PostCard } from './post-card';
import {
  countOfTopic,
  FEATURED,
  INITIAL,
  isBrowsing,
  LOOP_AFTER_MS,
  postsIn,
  reducer,
  RESTING,
  SCRIPT,
  type TopicFilter,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const FILTERS: { id: TopicFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  ...TOPICS,
];

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

const ARRIVED = { opacity: 1, y: 0 };

const ARRIVING = { opacity: 0, y: 8 };

const FADED = { opacity: 0, y: 0 };

const ARRIVE: Transition = { duration: 0.25, ease: EASE_OUT_STRONG };

const LEAVE: Transition = { duration: 0.12, ease: EASE_OUT_STRONG };

function arrivingOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADED;
  }
  return ARRIVING;
}

function glideOf(shouldReduceMotion: boolean): Transition {
  if (shouldReduceMotion) {
    return { ...ARRIVE, layout: INSTANT };
  }
  return { ...ARRIVE, layout: SLOW_SPRING };
}

function filterOf(values: unknown[]) {
  const [value] = values;
  const filter = FILTERS.find((candidate) => candidate.id === value);
  return filter?.id;
}

function shownLineOf(shown: number, total: number) {
  if (total === 1) {
    return 'Showing the only post';
  }
  return `Showing ${shown} of ${total} posts`;
}

function emptyLineOf(query: string, topic: TopicFilter) {
  const trimmed = query.trim();
  const filter = FILTERS.find((candidate) => candidate.id === topic);
  const topicLabel = filter?.label ?? 'this topic';
  const hasTopic = topic !== 'all';
  if (trimmed === '') {
    return `Nothing in ${topicLabel} yet`;
  }
  if (hasTopic) {
    return `No ${topicLabel} post mentions “${trimmed}”`;
  }
  return `No post mentions “${trimmed}”`;
}

export default function Blog01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const posts = postsIn(state);
  const shownPosts = posts.slice(0, state.visible);
  const shownCount = shownPosts.length;
  const hasMore = posts.length > shownCount;
  const isEmpty = posts.length === 0;
  const showsFeatured = isBrowsing(state);
  const layoutKey = shownPosts.map((post) => post.id).join(' ');
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;
  useKeptHeight(ref);

  function pickTopic(values: unknown[]) {
    const topic = filterOf(values);
    if (topic) {
      act({ type: 'topicPicked', topic });
    }
  }

  /** The button leaves with the empty state, so the focus goes to the search it emptied. */
  function showAll() {
    act({ type: 'cleared' });
    requestAnimationFrame(() => {
      const search = ref.current?.querySelector<HTMLElement>('[data-search]');
      search?.focus();
    });
  }

  /** The first card that arrives takes the focus, so the keyboard carries on where the reading does. */
  function loadMore() {
    const firstNew = posts[shownCount];
    act({ type: 'loadedMore' });
    if (!firstNew) {
      return;
    }
    requestAnimationFrame(() => {
      const selector = `[data-post="${firstNew.id}"] a`;
      const link = ref.current?.querySelector<HTMLElement>(selector);
      link?.focus();
    });
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col px-4 py-8 @2xl:px-8 @2xl:py-12'>
          <header className='flex flex-col gap-4 pb-8'>
            <div className='flex min-h-7 items-center gap-2 text-[13px]'>
              <CompanyMark seed={BLOG.company} />
              <span className='font-medium'>{BLOG.company}</span>
              <span className='text-muted-foreground'>/ Blog</span>
              <span className='flex-1' />
              <ReplayButton
                isShown={canReplay}
                onReplay={restart}
                label='Replay'
              />
            </div>
            <div className='flex flex-col gap-2'>
              <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
                {BLOG.name}
              </h1>
              <p className='text-muted-foreground max-w-xl text-sm text-pretty'>
                {BLOG.lead}
              </p>
            </div>
          </header>

          <AnimatePresence initial={false}>
            {showsFeatured && (
              <motion.div
                key='featured'
                className='-mx-1 -mt-1 overflow-hidden px-1 pt-1'
                {...rowPresenceOf(shouldReduceMotion)}
              >
                <div className='pb-8'>
                  <FeaturedPost post={FEATURED} />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className='flex flex-col gap-8'>
            <div className='flex flex-col gap-3 @2xl:flex-row @2xl:items-center'>
              <ToggleGroup
                aria-label='Topics'
                value={[state.topic]}
                onValueChange={pickTopic}
                travel
                indicatorClassName={THUMB}
                className='bg-foreground/[0.04] flex-wrap rounded-xl p-1'
              >
                {FILTERS.map((filter) => (
                  <ToggleGroupItem
                    key={filter.id}
                    value={filter.id}
                    className={cn(
                      'h-7 gap-1.5 rounded-lg px-2.5 text-xs',
                      pressedQuietOf(pressed === `topic-${filter.id}`)
                    )}
                  >
                    {filter.label}
                    <span className='text-muted-foreground tabular-nums'>
                      {countOfTopic(filter.id)}
                    </span>
                  </ToggleGroupItem>
                ))}
              </ToggleGroup>
              <div className='relative w-full @2xl:ms-auto @2xl:w-60'>
                <SearchIcon className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2' />
                <Input
                  type='search'
                  data-search
                  aria-label='Search posts'
                  placeholder='Search posts'
                  autoComplete='off'
                  value={state.query}
                  onChange={(event) =>
                    act({ type: 'searched', query: event.target.value })
                  }
                  className='ps-8'
                />
              </div>
            </div>

            {isEmpty && (
              <div className='bg-foreground/[0.025] flex flex-col items-center gap-3 rounded-2xl px-6 py-14 text-center transition-opacity duration-200 starting:opacity-0'>
                <span className='keycap-3d flex size-10 items-center justify-center rounded-xl'>
                  <SearchIcon className='text-muted-foreground size-5' />
                </span>
                <p className='text-sm font-medium text-balance'>
                  {emptyLineOf(state.query, state.topic)}
                </p>
                <p className='text-muted-foreground max-w-sm text-[13px] text-pretty'>
                  Try a shorter word, or look through every topic.
                </p>
                <Button type='button' variant='outline' onClick={showAll}>
                  Show all posts
                </Button>
              </div>
            )}

            {!isEmpty && (
              <ul className='relative grid gap-x-3 gap-y-5 @lg:grid-cols-2 @3xl:grid-cols-3'>
                <AnimatePresence mode='popLayout' initial={false}>
                  {shownPosts.map((post) => (
                    <motion.li
                      key={post.id}
                      data-post={post.id}
                      layout
                      layoutDependency={layoutKey}
                      initial={arrivingOf(shouldReduceMotion)}
                      animate={ARRIVED}
                      exit={{ opacity: 0, transition: LEAVE }}
                      transition={glideOf(shouldReduceMotion)}
                    >
                      <PostCard post={post} />
                    </motion.li>
                  ))}
                </AnimatePresence>
              </ul>
            )}

            {!isEmpty && (
              <div className='flex flex-col items-center gap-3'>
                <p className='text-muted-foreground text-xs tabular-nums'>
                  <WordRoll
                    text={shownLineOf(shownCount, posts.length)}
                    value={shownCount}
                  />
                </p>
                {hasMore && (
                  <Button
                    type='button'
                    variant='outline'
                    onClick={loadMore}
                    className={pressedQuietOf(pressed === 'load-more')}
                  >
                    Load more posts
                  </Button>
                )}
              </div>
            )}
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Wash } from '@/registry/ndeko/ui/wash';

import { Cover } from './cover';
import { topicOf, type Post } from './data';

const LINK =
  'group flex h-full rounded-xl transition-[background-color,scale] duration-150 ease-(--ease-out-strong) active:scale-[0.97]';

function TopicLine({ post }: { post: Post }) {
  const topic = topicOf(post.topic);
  const color = seriesColorOf(topic.series);

  return (
    <p className='flex items-center gap-2 text-xs'>
      <Chip color={color}>{topic.label}</Chip>
      <span className='text-muted-foreground tabular-nums'>
        {post.minutes} min read
      </span>
    </p>
  );
}

function Byline({ post }: { post: Post }) {
  return (
    <p className='flex min-w-0 items-center gap-2 text-xs'>
      <Avatar seed={post.author} className='size-5' />
      <span className='truncate'>{post.author}</span>
      <span aria-hidden='true' className='text-muted-foreground'>
        ·
      </span>
      <time dateTime={post.isoDate} className='text-muted-foreground shrink-0'>
        {post.date}
      </time>
    </p>
  );
}

export function PostCard({ post }: { post: Post }) {
  return (
    <article className='h-full'>
      <a
        href={post.href}
        className={cn(
          LINK,
          'hover:bg-foreground/[0.03] flex-col gap-3 p-2',
          FOCUS_RING
        )}
      >
        <Cover topic={post.topic} seed={post.id} />
        <div className='flex flex-1 flex-col gap-2 px-1 pb-1'>
          <TopicLine post={post} />
          <h3 className='text-base font-semibold text-balance'>{post.title}</h3>
          <p className='text-muted-foreground line-clamp-3 text-[13px] text-pretty'>
            {post.excerpt}
          </p>
          <div className='mt-auto pt-1'>
            <Byline post={post} />
          </div>
        </div>
      </a>
    </article>
  );
}

export function FeaturedPost({ post }: { post: Post }) {
  return (
    <article className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] relative isolate rounded-2xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <Wash />
      <a
        href={post.href}
        className={cn(
          LINK,
          'flex-col gap-4 p-2 active:scale-[0.99] @3xl:grid @3xl:grid-cols-[1.1fr_1fr] @3xl:gap-6',
          FOCUS_RING
        )}
      >
        <Cover topic={post.topic} seed={post.id} size='featured' />
        <div className='flex flex-col gap-3 px-2 pb-2 @3xl:py-6 @3xl:pe-6'>
          <p className='text-primary-ink text-xs font-medium'>Latest post</p>
          <TopicLine post={post} />
          <h2 className='text-xl font-semibold text-balance @3xl:text-2xl'>
            {post.title}
          </h2>
          <p className='text-muted-foreground text-sm text-pretty'>
            {post.excerpt}
          </p>
          <div className='mt-auto pt-2'>
            <Byline post={post} />
          </div>
        </div>
      </a>
    </article>
  );
}

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { hatchOf } from '@/registry/ndeko/lib/hatch';
import { hashOf, pickedFrom } from '@/registry/ndeko/lib/seeded';
import { cn } from '@/registry/ndeko/lib/utils';

import { TOPIC_GLYPH, topicOf, type TopicId } from './data';

type CoverStyle = React.CSSProperties & { '--topic': string };

type GemStyle = React.CSSProperties & { '--gem': string };

type Placement = {
  gem: string;
  near: string;
  far: string;
};

/** A post always lands on the same placement, so its cover never changes between visits. */
const PLACEMENTS: Placement[] = [
  {
    gem: 'left-[24%] top-[52%]',
    near: 'left-[40%] top-[30%]',
    far: 'left-[54%] top-[66%]',
  },
  {
    gem: 'left-1/2 top-[46%]',
    near: 'left-[30%] top-[66%]',
    far: 'left-[70%] top-[28%]',
  },
  {
    gem: 'left-[72%] top-[52%]',
    near: 'left-[54%] top-[28%]',
    far: 'left-[38%] top-[66%]',
  },
];

const PLATE = 'absolute -translate-x-1/2 -translate-y-1/2';

const GHOST =
  'bg-[color-mix(in_oklab,var(--topic)_10%,transparent)] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--topic)_30%,transparent)]';

const SIZE_CLASS = {
  card: {
    frame: 'aspect-[16/9] rounded-lg',
    gem: 'size-12 rounded-[14px] [&_svg]:size-6',
    ghost: 'size-9 rounded-[11px]',
  },
  featured: {
    frame: 'aspect-[16/9] rounded-xl @3xl:aspect-auto @3xl:h-full',
    gem: 'size-16 rounded-[18px] [&_svg]:size-8',
    ghost: 'size-12 rounded-[14px]',
  },
};

type CoverProps = {
  topic: TopicId;
  seed: string;
  size?: keyof typeof SIZE_CLASS;
};

export function Cover({ topic, seed, size = 'card' }: CoverProps) {
  const Glyph = TOPIC_GLYPH[topic];
  const { series } = topicOf(topic);
  const color = seriesColorOf(series);
  const hash = hashOf(seed);
  const placement = pickedFrom(PLACEMENTS, hash);
  const sizeClass = SIZE_CLASS[size];
  const coverStyle: CoverStyle = {
    '--topic': color,
    backgroundColor: 'color-mix(in oklab, var(--topic) 9%, var(--card))',
  };
  const hatchStyle = {
    backgroundImage: hatchOf('var(--topic)', 14),
    maskImage: 'linear-gradient(to left, black, transparent 75%)',
  };
  const gemStyle: GemStyle = { '--gem': color };

  return (
    <div
      aria-hidden='true'
      style={coverStyle}
      className={cn('relative isolate w-full overflow-hidden', sizeClass.frame)}
    >
      <span style={hatchStyle} className='absolute inset-0' />
      <span className={cn(PLATE, GHOST, sizeClass.ghost, placement.far)} />
      <span className={cn(PLATE, GHOST, sizeClass.ghost, placement.near)} />
      <span
        style={gemStyle}
        className={cn(
          PLATE,
          'gem-plate flex items-center justify-center',
          sizeClass.gem,
          placement.gem
        )}
      >
        <Glyph />
      </span>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { POSTS, topicOf, type Post, type TopicId } from './data';

export type TopicFilter = TopicId | 'all';

export type BlogState = {
  topic: TopicFilter;
  query: string;
  visible: number;
  spoken: string;
};

export type BlogAction =
  | { type: 'topicPicked'; topic: TopicFilter }
  | { type: 'searched'; query: string }
  | { type: 'loadedMore' }
  | { type: 'cleared' };

type Step = SessionStep<BlogState, BlogAction>;

export const PAGE_SIZE = 6;

/** One more row of the widest grid. */
const LOAD_STEP = 3;

export const FEATURED = POSTS[0];

export const INITIAL: BlogState = {
  topic: 'all',
  query: '',
  visible: PAGE_SIZE,
  spoken: '',
};

function wordsOf(query: string) {
  const trimmed = query.trim();
  const lowered = trimmed.toLowerCase();
  const pieces = lowered.split(/\s+/);
  return pieces.filter((piece) => piece !== '');
}

function matchesQuery(post: Post, words: string[]) {
  const text = `${post.title} ${post.excerpt}`.toLowerCase();
  return words.every((word) => text.includes(word));
}

function matchesTopic(post: Post, topic: TopicFilter) {
  if (topic === 'all') {
    return true;
  }
  return post.topic === topic;
}

/** With no topic and no search, the newest post sits apart as the featured one. */
export function isBrowsing(state: BlogState) {
  const hasQuery = wordsOf(state.query).length > 0;
  return state.topic === 'all' && !hasQuery;
}

export function postsIn(state: BlogState) {
  const words = wordsOf(state.query);
  const matching = POSTS.filter((post) => {
    const isInTopic = matchesTopic(post, state.topic);
    return isInTopic && matchesQuery(post, words);
  });
  if (isBrowsing(state)) {
    return matching.filter((post) => post.id !== FEATURED.id);
  }
  return matching;
}

export function countOfTopic(topic: TopicFilter) {
  const inTopic = POSTS.filter((post) => matchesTopic(post, topic));
  return inTopic.length;
}

function postsWordOf(count: number) {
  if (count === 1) {
    return '1 post';
  }
  return `${count} posts`;
}

function topicNameOf(topic: TopicFilter) {
  if (topic === 'all') {
    return 'all topics';
  }
  return topicOf(topic).label;
}

function foundLineOf(state: BlogState) {
  const count = postsIn(state).length;
  if (count === 0) {
    return 'No posts match';
  }
  return `${postsWordOf(count)} in ${topicNameOf(state.topic)}`;
}

function filtered(state: BlogState, change: Partial<BlogState>): BlogState {
  const next = { ...state, ...change, visible: PAGE_SIZE };
  return { ...next, spoken: foundLineOf(next) };
}

function loadedMore(state: BlogState): BlogState {
  const total = postsIn(state).length;
  const visible = Math.min(state.visible + LOAD_STEP, total);
  const added = visible - state.visible;
  if (added <= 0) {
    return state;
  }
  return { ...state, visible, spoken: `${postsWordOf(added)} more` };
}

export function reducer(state: BlogState, action: BlogAction): BlogState {
  switch (action.type) {
    case 'topicPicked':
      return filtered(state, { topic: action.topic });
    case 'searched':
      return filtered(state, { query: action.query });
    case 'loadedMore':
      return loadedMore(state);
    case 'cleared':
      return filtered(state, { topic: 'all', query: '' });
  }
}

/**
 * A reader loads another row, narrows to Design and comes back to every topic. Picking a topic
 * starts the list from its first page, so the round ends on the page it began with.
 */
export const SCRIPT: Step[] = [
  {
    after: 1700,
    by: 'demo',
    press: 'load-more',
    action: { type: 'loadedMore' },
  },
  {
    after: 2600,
    by: 'demo',
    press: 'topic-design',
    action: { type: 'topicPicked', topic: 'design' },
  },
  {
    after: 2800,
    by: 'demo',
    press: 'topic-all',
    action: { type: 'topicPicked', topic: 'all' },
  },
];

export const RESTING: BlogState = INITIAL;

export const LOOP_AFTER_MS = 2600;

